import{z as l,x as o,o as r,c as p,q as A,j as i,D as B,d as a,s,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"噪声交易者风险 DSSW","description":"","frontmatter":{"title":"噪声交易者风险 DSSW","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/noise-trader-risk.md","filePath":"econ/noise-trader-risk.md","lastUpdated":1791063341000}'),d={name:"econ/noise-trader-risk.md"};function D(m,E,S,h,C,f){const n=o("Mermaid");return r(),p("div",null,[E[2]||(E[2]=A('<h1 id="噪声交易者风险-dssw" tabindex="-1">噪声交易者风险 DSSW <a class="header-anchor" href="#噪声交易者风险-dssw" aria-label="Permalink to &quot;噪声交易者风险 DSSW&quot;">​</a></h1><div class="epigraph"><p>即使价格已经偏离基本面，套利者也不敢把仓位加满：噪声交易者明天可能更错，短期亏损会先要了资本的命。</p><footer>—— De Long, Shleifer, Summers and Waldmann, Noise Trader Risk in Financial Markets, JPE 1990</footer></div><p><a href="/econ/experimental-methods">上一课</a>把偏差留在实验室与田野。本课打开市场单元。缺口是：若有理性套利者，实验室零件为何还能进价格？DSSW 的回答不是「没有套利者」，而是套利者面对<strong>不可分散的噪声交易者风险</strong>。不重写 <a href="/econ/emh">EMH</a> 的信息分层，不进入限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Friedman 的经典反驳：非理性会被套利消灭。DSSW（1990）建两期重叠世代：安全资产与供给固定的不安全资产，后者基本面已知。噪声交易者对基本面的错误信念随机；理性交易者最大化下期财富，厌恶风险，生命有限。均衡价格含一项噪声溢价：错误可以持续并扩大，理性者不愿完全抵消。噪声交易者甚至可能赚得比理性者还多——因为他们多承担了自己制造的风险。</p><p>缺口是给「偏差如何存活」第一块均衡零件，而不是再列过度自信。</p><p><span class="marginnote">「噪声交易者」不是贬义的散户标签，而是模型里一类需求的代称：他们的买卖不基于基本面信息，像收到随机信号一样进出。把他们的净需求想成一阵阵吹向市场的随机风，价格就是在这阵风里漂的船。</span></p><p><span class="marginnote">噪声交易者风险与基本面风险不同：即使股息确定，价格路径仍随机，因为别人的信念随机。有限寿命使套利者无法等到信念回归。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两资产、均值方差偏好、噪声需求外生随机。求解理性者对不安全资产的需求，市场出清得价格。错定价的方差进入理性者的一阶条件，像额外风险。比较两者的期望收益：噪声交易者若平均看多，持有更多风险资产，可以有更高期望财富。本课不估计噪声方差。</p>',10)),(r(),i(t,null,{default:B(()=>[s(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FRI%5B%22Friedman%3A%20%E5%A5%97%E5%88%A9%E6%B6%88%E7%81%AD%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20DSSW%5B%22%E6%9C%89%E9%99%90%E5%AF%BF%E5%91%BD%E5%A5%97%E5%88%A9%E8%80%85%22%5D%0A%20%20DSSW%20--%3E%20NTR%5B%22%E5%99%AA%E5%A3%B0%E4%BA%A4%E6%98%93%E8%80%85%E9%A3%8E%E9%99%A9%E4%B8%8D%E5%8F%AF%E5%88%86%E6%95%A3%22%5D%0A%20%20NTR%20--%3E%20MIS%5B%22%E9%94%99%E5%AE%9A%E4%BB%B7%E5%9C%A8%E5%9D%87%E8%A1%A1%E4%B8%AD%E5%AD%98%E6%B4%BB%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"主干在限价簿交接处已停。本课是补层理论：对象仍是均衡价格 \\(p\\)，不是队列。量化栏的做市商存货不要写进来。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,[a("机制是风险。套利不是无风险的：你买低估资产时，噪声交易者可能明天更悲观，你必须在生命结束前卖出。风险厌恶使抵消仓位有限。因此价格可以偏离基本面而不被立刻修平。这与"),e("a",{href:"/econ/equity-premium-puzzle"},"股权溢价"),a("的 \\(m\\) 语言相容：多出来的风险可以要求溢价，只是风险来自别人的错误，不是来自消费。")],-1)),(r(),i(t,null,{default:B(()=>[s(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%A5%97%E5%88%A9%E8%80%85%E5%8F%91%E7%8E%B0%E4%BB%B7%E6%A0%BC%E4%BD%8E%E4%BC%B0%22%5D%20--%3E%20W%5B%22%E5%8A%A0%E4%BB%93%E4%B9%B0%E5%85%A5%EF%BC%8C%E6%8A%BC%E6%B3%A8%E5%9B%9E%E5%BD%92%E5%9F%BA%E6%9C%AC%E9%9D%A2%22%5D%0A%20%20W%20--%3E%20Q%7B%22%E6%98%8E%E5%A4%A9%E5%99%AA%E5%A3%B0%E4%BA%A4%E6%98%93%E8%80%85%E6%9B%B4%E6%82%B2%E8%A7%82%E8%BF%98%E6%98%AF%E8%BD%AC%E5%90%91%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9B%B4%E6%82%B2%E8%A7%82%22%7C%20DEEP%5B%22%E4%BD%8E%E4%BC%B0%E6%9B%B4%E6%B7%B1%EF%BC%8C%E7%9F%AD%E6%9C%9F%E6%B5%AE%E4%BA%8F%22%5D%0A%20%20DEEP%20--%3E%20OUT%5B%22%E8%A2%AB%E8%BF%AB%E5%9C%A8%E4%BA%8F%E6%8D%9F%E4%B8%AD%E5%B9%B3%E4%BB%93%E7%A6%BB%E5%9C%BA%22%5D%0A%20%20Q%20--%3E%7C%22%E4%BF%A1%E5%BF%B5%E5%9B%9E%E5%BD%92%22%7C%20WIN%5B%22%E9%94%99%E5%AE%9A%E4%BB%B7%E6%94%B6%E6%95%9B%EF%BC%8C%E5%A5%97%E5%88%A9%E8%90%BD%E8%A2%8B%22%5D%0A%20%20DIVER%5B%22%E3%80%8C%E6%9B%B4%E9%94%99%E3%80%8D%E7%9A%84%E5%8F%AF%E8%83%BD%E6%97%A0%E6%B3%95%E9%9D%A0%E5%88%86%E6%95%A3%E6%B6%88%E9%99%A4%22%5D%20--%3E%20KEEP%5B%22%E6%89%80%E4%BB%A5%E7%90%86%E6%80%A7%E4%BB%93%E4%BD%8D%E6%B0%B8%E8%BF%9C%E7%95%99%E6%9C%89%E4%BD%99%E5%9C%B0%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">数字感受「等不起」：假设错定价平均三年才收敛。用自己的无限期资金慢慢等，收益最终仍能落袋；若是管别人钱的经理，客户半年就赎回，第二年浮亏 10% 时仓位已被砍——收敛还没等到，人先出局了。DSSW 用有限寿命模拟的正是这种期限压力。</span></p><p>下一课 Shleifer–Vishny 把「有限寿命」换成「委托资本」：专业套利者会被短期亏损赎回。</p><p>DSSW 的不安全资产股息可以是常数，价格仍抖——抖来自噪声需求。这与消费 SDF 的风险不是同一来源：这里 \\(m\\) 若仍是消费核，溢价来自噪声与消费的协方差，不必很大；但套利者自己的定价核含噪声方差。有限寿命关掉「等到 \\(T=\\infty\\) 信念回归」。主干停在簿的交接处；本课 \\(p\\) 仍是出清价，没有队列。噪声交易者不是实验室被试的别名，是需求冲击的均衡载体。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>DSSW 的噪声是外生情绪，没有微观启发式。重叠世代是技术，不是人口学主张。完全无限寿命加无赎回的套利者会削弱机制。本课也不处理封闭式基金折价的全部经验——那是应用，DSSW 原文用它当动机。</p><p>后课默认：噪声交易者风险是错定价存活的需求侧风险；套利限制是资本与委托的供给侧。</p><p><span class="marginnote">常见误区：以为「市场里有聪明钱，所以错定价立刻被吃掉」。DSSW 的要点恰是聪明钱也要算风险收益——当抵消错定价本身带来不可分散、期限又不确定的风险时，不加满仓才是理性的，错定价因此存活。</span></p><p>股息可确定，价格仍抖，因为别人的信念随机；有限寿命使套利者无法等到回归。</p><p>主干交给量化栏的是协议；本课 \\(p\\) 仍是出清价。噪声是需求冲击的均衡载体。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>噪声交易者让价格路径本身成为风险，有限套利者不敢完全抵消。</li><li>错误可以在均衡中存活，甚至给噪声交易者更高期望收益。</li><li>不重写 EMH 分层，不写簿；补层问的是均衡里的风险。</li><li>噪声交易者可以因多承担自己制造的风险而期望收益更高。</li><li>方向尚未给出，只解释存活。</li><li>出处：De Long, Shleifer, Summers and Waldmann, <em>JPE</em> 1990。</li></ul>',11))])}const c=l(d,[["render",D]]);export{F as __pageData,c as default};
